spec.expr:
100 *
sum by (container) (
  container_memory_working_set_bytes{
    namespace="opsboard",
    container!="",
    container!="POD"
  }
)
/
sum by (container) (
  kube_pod_container_resource_limits{
    namespace="opsboard",
    resource="memory",
    unit="byte"
  }
)

100 *
sum by (container) (
  rate(container_cpu_usage_seconds_total{
    namespace="opsboard",
    container!="",
    container!="POD"
  }[5m])
)
/
sum by (container) (
  kube_pod_container_resource_limits{
    namespace="opsboard",
    resource="cpu",
    unit="core"
  }
)

max by (component) (
  label_replace(
    (
      kube_deployment_status_replicas_available{
        namespace="opsboard",
        deployment=~"vote|result|worker|redis"
      } > bool 0
    ),
    "component", "$1", "deployment", "(.*)"
  )
  or
  label_replace(
    (
      kube_statefulset_status_replicas_ready{
        namespace="opsboard",
        statefulset="postgres"
      } > bool 0
    ),
    "component", "$1", "statefulset", "(.*)"
  )
)

sum by (container) (
  rate(
    container_cpu_usage_seconds_total{
      namespace="opsboard",
      container!="",
      container!="POD"
    }[5m]
  )
)

sum by (container) (
  container_memory_working_set_bytes{
    namespace="opsboard",
    container!="",
    container!="POD"
  }
)

sum by (container) (
  rate(container_cpu_usage_seconds_total{
    namespace="opsboard",
    container!="",
    container!="POD"
  }[5m])
)

sum by (container) (
  rate(container_cpu_usage_seconds_total{
    namespace="opsboard",
    container!="",
    container!="POD"
  }[5m])
)

sum by (container) (
  container_memory_working_set_bytes{
    namespace="opsboard",
    container!="",
    container!="POD"
  }
)
